 CREATE OR REPLACE FUNCTION public.youthfacesheetbs(i_intakenumber character varying)                                                                                                                                                                                                                                                                                                                                                                   
  RETURNS TABLE(youthname character varying, youthid character varying, address1 character varying, address2 character varying, dateofbirth character varying, race character varying, height_in character varying, weight_lbs character varying, gender character varying, hair_color character varying, eye_color character varying, phone character varying, education json, physician json, insurance json, medical_condition json, medication json)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                      
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                        
    BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                             
          RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                
         (                                                                                                                                                                                                                                                                                                                                                                                                                                            
            select                                                                                                                                                                                                                                                                                                                                                                                                                                    
      cast(p.firstname ||' ' || p.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                                                                                                                        
                 cast(p.cjamspid as character varying) as youthid,                                                                                                                                                                                                                                                                                                                                                                                    
                 CAST(pa.address||','||pa.address2 as character varying) as address1,                                                                                                                                                                                                                                                                                                                                                                 
                 CAST(pa.county||' '|| pa.state|| ' '||pa.zipcode as character varying) as address2,                                                                                                                                                                                                                                                                                                                                                  
                 cast(to_char(p.dob, 'MM/DD/YYYY') as character varying) as dob,                                                                                                                                                                                                                                                                                                                                                                      
                 (select distinct typedescription from racetype where racetypekey=p.racetypekey) as race,                                                                                                                                                                                                                                                                                                                                             
                 cast(p.heightinfoot as character varying) as height,                                                                                                                                                                                                                                                                                                                                                                                 
                 cast(p.weightinlb as character varying) as weight,                                                                                                                                                                                                                                                                                                                                                                                   
                 (select distinct typedescription from gendertype where gendertypekey=p.gendertypekey) as gender,                                                                                                                                                                                                                                                                                                                                     
                 cast(p.haircolortypekey as character varying) as hair_color,                                                                                                                                                                                                                                                                                                                                                                         
         cast(p.eyecolortypekey as character varying) as eye_color,                                                                                                                                                                                                                                                                                                                                                                                   
         cast(ppn.phonenumber as character varying) as phone,                                                                                                                                                                                                                                                                                                                                                                                         
                 (select row_to_json(x) from                                                                                                                                                                                                                                                                                                                                                                                                          
                         (select pe.educationname as school,                                                                                                                                                                                                                                                                                                                                                                                          
                                 (select distinct typedescription from gradetype where gradetypekey=pe.currentgradetypekey) as lastgrade,                                                                                                                                                                                                                                                                                                             
                                 pe.enddate as enddate,                                                                                                                                                                                                                                                                                                                                                                                               
                                 (select countyname from county where countyid = pe.countyid) as county,                                                                                                                                                                                                                                                                                                                                              
                                 (select distinct typedescription from educationtype where educationtypekey = pe.specialeducationtypekey) as specialeducation,                                                                                                                                                                                                                                                                                        
                                 to_char(pet.readingtestdate, 'MM/DD/YYYY') as readdate,                                                                                                                                                                                                                                                                                                                                                              
                                 pet.readinglevel as readlevel,                                                                                                                                                                                                                                                                                                                                                                                       
                                 to_char(pet.mathtestdate, 'MM/DD/YYYY') as mathdate,                                                                                                                                                                                                                                                                                                                                                                 
                                 pet.mathlevel as mathlevel                                                                                                                                                                                                                                                                                                                                                                                           
                                 from personeducation pe where pe.personid=p.personid order by pe.startdate desc limit 1                                                                                                                                                                                                                                                                                                                              
                         ) as x                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ) as education,                                                                                                                                                                                                                                                                                                                                                                                                                      
                 (select row_to_json(x) from                                                                                                                                                                                                                                                                                                                                                                                                          
                         ( select ppi.name as name,                                                                                                                                                                                                                                                                                                                                                                                                   
                                 ppi.phone as phone                                                                                                                                                                                                                                                                                                                                                                                                   
                                 from personphycisianinfo ppi where ppi.personid = p.personid and ppi.isprimaryphycisian = true                                                                                                                                                                                                                                                                                                                       
                         ) as x                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ) as physician,                                                                                                                                                                                                                                                                                                                                                                                                                      
                 (select row_to_json(x) from                                                                                                                                                                                                                                                                                                                                                                                                          
                         (select phi.medicalinsuranceprovider as provider,                                                                                                                                                                                                                                                                                                                                                                            
                                 phi.policyname as policyname,                                                                                                                                                                                                                                                                                                                                                                                        
                                 phi.expirationdate as expirationdate                                                                                                                                                                                                                                                                                                                                                                                 
                         from personhealthinsurance phi where phi.personid = p.personid                                                                                                                                                                                                                                                                                                                                                               
                         ) as x                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ) as insurance,                                                                                                                                                                                                                                                                                                                                                                                                                      
                 (select json_agg(x) from                                                                                                                                                                                                                                                                                                                                                                                                             
                         (select phe.outcomeresults as condition,                                                                                                                                                                                                                                                                                                                                                                                     
                                 phe.notes as notes                                                                                                                                                                                                                                                                                                                                                                                                   
                         from personhealthexamination phe where phe.personid = p.personid                                                                                                                                                                                                                                                                                                                                                             
                         ) as x                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ) as medical_condition,                                                                                                                                                                                                                                                                                                                                                                                                              
                 (select json_agg(x) from                                                                                                                                                                                                                                                                                                                                                                                                             
                         (select pmpc.medicationname as medication,                                                                                                                                                                                                                                                                                                                                                                                   
                         pmpc.dosage as dosage                                                                                                                                                                                                                                                                                                                                                                                                        
                         from personmedicpshychotropic pmpc where pmpc.personid = p.personid                                                                                                                                                                                                                                                                                                                                                          
                         ) as x                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ) as medication                                                                                                                                                                                                                                                                                                                                                                                                                      
        from intakedastaging da                                                                                                                                                                                                                                                                                                                                                                                                                       
        left join person p on da.focuspersonid = p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                                                                        
        left join personeducation pe on p.personid = pe.personid and pe.activeflag=1                                                                                                                                                                                                                                                                                                                                                                  
        left join personphonenumber ppn on p.personid = ppn.personid and ppn.activeflag=1                                                                                                                                                                                                                                                                                                                                                             
        left join personaddress pa on pa.personid=p.personid and pa.activeflag=1                                                                                                                                                                                                                                                                                                                                                                      
         left join personeducationtesting pet on pet.personid=p.personid and pet.activeflag=1                                                                                                                                                                                                                                                                                                                                                         
         left join personphycisianinfo  ppi on ppi.personid=p.personid and ppi.activeflag=1                                                                                                                                                                                                                                                                                                                                                           
         left join personhealthinsurance phi on phi.personid=p.personid and phi.activeflag=1                                                                                                                                                                                                                                                                                                                                                          
         left join personhealthexamination phe on phe.personid=p.personid and phe.activeflag=1                                                                                                                                                                                                                                                                                                                                                        
         left join personmedicpshychotropic pmpc on pmpc.personid=p.personid and pmpc.activeflag=1                                                                                                                                                                                                                                                                                                                                                    
        where da.intakenumber = i_intakenumber and da.activeflag=1);                                                                                                                                                                                                                                                                                                                                                                                  
    end;                                                                                                                                                                                                                                                                                                                                                                                                                                              
   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                           

